const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={agents:[{id:'wiki-assistant',name:'研发知识助手',desc:'检索团队 Wiki 与数据表结构，整理有依据的技术回答。',model:'deepseek-chat',mode:'plan',prompt:'你是团队的研发知识助手。优先检索已绑定知识库，回答标注引用。复杂任务先制定计划再执行。不得将 SQL 文档当作数据库执行指令。',skills:['wiki-research'],tools:['wiki-search'],wiki:['团队 Wiki'],subs:[],published:1},{id:'sql-reviewer',name:'SQL 审查助手',desc:'结合数据字典审查 SQL，解释查询逻辑与潜在问题。',model:'gpt-model-id',mode:'react',prompt:'你是 SQL 审查助手，结合数据字典提供建议，不执行数据库写操作。',skills:['sql-review'],tools:[],wiki:['数据字典'],subs:[],published:1},{id:'release-planner',name:'发布计划助手',desc:'自动拆解发布任务，调用子 Agent 收集信息并汇总。',model:'deepseek-chat',mode:'plan',prompt:'根据用户需求生成并执行发布准备计划。',skills:[],tools:[],wiki:[],subs:['sql-reviewer'],published:0}],skills:[{name:'wiki-research',description:'检索知识、整理引用与生成报告',source:'Git · team/skills',version:'v1.2.0'},{name:'sql-review',description:'读取 SQL 文件并进行审查',source:'文件夹上传',version:'v1.0.0'}],tools:[{name:'wiki-search',description:'搜索团队文档',source:'外部 MCP',version:'3 个工具'},{name:'text-utils',description:'文本抽取与格式转换',source:'平台托管',version:'2 个工具'}],models:[{name:'deepseek-chat',description:'DeepSeek',source:'https://api.deepseek.com',version:'演示配置'},{name:'gpt-model-id',description:'OpenAI · 模型 ID 可配置',source:'https://api.openai.com/v1',version:'演示配置'}],wiki:[{name:'团队 Wiki',description:'架构与研发流程',source:'Markdown / TXT',version:'12 个文件'},{name:'数据字典',description:'业务表结构与 SQL 示例',source:'SQL',version:'4 个文件'}]};
let db;try{db=JSON.parse(localStorage.getItem('agent-loom-demo-v1')||localStorage.getItem('eddy-demo-v1'))||structuredClone(seed)}catch{db=structuredClone(seed)}
function migrateSubs(a){a.subs=(a.subs||[]).map(x=>{if(typeof x==='object'){delete x.mode;return x;}const old=db.agents.find(r=>r.id===x);return {id:'template-'+x,name:old?.name||'任务执行助手',desc:old?.desc||'处理复杂子任务',prompt:old?.prompt||'',skills:[...(old?.skills||[])],tools:[...(old?.tools||[])],wiki:[...(old?.wiki||[])]}})}
for(const a of db.agents){migrateSubs(a);if(a.snapshot)migrateSubs(a.snapshot);if(a.published&&!a.snapshot)a.snapshot=structuredClone({...a,snapshot:undefined})}

let page='agents',current=db.agents[0].id,tab='chat',filter='',busy=false,chat=[],timers=[];
const items=[['agents','◈','Agents'],['skills','▧','Skills'],['tools','⌘','工具'],['models','◉','模型连接'],['wiki','▤','知识库'],['members','♧','空间成员']];
const save=()=>localStorage.setItem('agent-loom-demo-v1',JSON.stringify(db));
const notify=s=>{$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)};
function navigate(p){timers.forEach(clearTimeout);timers=[];busy=false;page=p;filter='';chat=[];render()}
function nav(){ $('#nav').innerHTML=items.map(([p,i,n])=>`<button class="${page===p||page==='editor'&&p==='agents'||page==='use'&&p==='agents'?'active':''}" data-nav="${p}"><i>${i}</i>${n}</button>`).join('');$('#breadcrumb').textContent='产品研发空间 / '+(items.find(x=>x[0]===page)?.[2]||'Agents / '+(page==='use'?'发布应用':'开发配置')) }
const head=(title,desc,actions='')=>`<div class="pagehead"><div><h1>${title}</h1><span class="muted">${desc}</span></div><div class="actions">${actions}</div></div>`;
function render(){nav();const m=$('#main');if(page==='agents'){m.innerHTML=head('Agents','将模型、技能与工具组合成团队可用的 Agent。','<button class="primary" data-action="newagent">＋ 创建 Agent</button>')+`<div class="toolbar"><input id="search" aria-label="搜索 Agent" placeholder="搜索 Agent 名称" value="${esc(filter)}"><span class="muted">${db.agents.length} 个 Agent</span><span class="tag">团队共享</span></div><div class="cards" id="agentcards"></div>`;cards();return}if(page==='editor')return editor();if(page==='use')return use();if(page==='members'){m.innerHTML=head('空间成员','拥有空间权限的成员可以访问本空间的 Agent。')+'<div class="notice">第一版以空间成员访问为核心。以下成员与权限为演示数据。</div><div class="tablewrap" style="margin-top:20px"><table><tr><th>成员</th><th>邮箱</th><th>身份</th><th>加入时间</th></tr><tr><td>林晓</td><td>lin@example.com</td><td>空间管理者</td><td>2026-09-28</td></tr><tr><td>陈舟</td><td>chen@example.com</td><td>成员</td><td>2026-09-29</td></tr></table></div>';return}resources()}
function cards(){const list=db.agents.filter(a=>a.name.toLowerCase().includes(filter.toLowerCase()));$('#agentcards').innerHTML=list.length?list.map(a=>`<article class="card"><div class="cardtop"><div class="agenticon">${a.mode==='plan'?'≋':'✧'}</div><span class="tag ${a.published?'green':''}">${a.published?'已发布 v'+a.published:'草稿'}</span></div><h3>${esc(a.name)}</h3><div class="tags"><span class="tag">${esc(a.model)}</span><span class="tag purple">${a.mode==='plan'?'Plan':'ReAct'}</span></div><div class="cardfoot"><div class="count"><span><b>${a.skills.length}</b> 技能</span><span><b>${a.tools.length}</b> 工具</span></div><div class="actions">${a.published?`<button data-use="${a.id}">使用</button>`:''}<button data-edit="${a.id}">配置</button></div></div></article>`).join(''):'<div class="empty">没有匹配的 Agent</div>'}
function agent(){return db.agents.find(a=>a.id===current)}
function choices(type,values){return db[type].map(r=>`<label class="choice"><input type="checkbox" name="${type}" value="${esc(r.name)}" ${values.includes(r.name)?'checked':''}>${esc(r.name)}<span class="tag">${esc(r.source)}</span></label>`).join('')||'<p class="muted">还没有资源，请先在资源管理页添加。</p>'}
function editor(){const a=agent();$('#main').innerHTML=head(esc(a.name),`开发配置 / ${a.published?'已有发布版本 v'+a.published:'尚未发布'}`,'<button data-nav="agents">返回列表</button><button data-action="saveagent">保存草稿</button><button class="primary" data-action="publish">发布版本</button>')+`<div class="split"><div class="panel" id="config"><div class="section"><h2>基础配置</h2><div class="row"><div><label for="agentname">Agent 名称</label><input id="agentname" value="${esc(a.name)}"></div><div><label for="model">模型</label><select id="model">${db.models.map(r=>`<option ${a.model===r.name?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div></div><label for="prompt">系统 Prompt</label><textarea id="prompt" rows="5">${esc(a.prompt)}</textarea></div><div class="section"><h2>执行策略</h2><div class="modes"><button class="mode ${a.mode==='react'?'selected':''}" data-mode="react"><b>ReAct</b><small>逐步决策、调用工具并处理结果</small></button><button class="mode ${a.mode==='plan'?'selected':''}" data-mode="plan"><b>Plan</b><small>自动生成计划并执行各步骤</small></button></div></div><div class="section"><div class="sectionhead"><h2>Skills</h2><a href="#" data-nav="skills">管理技能</a></div>${choices('skills',a.skills)}</div><div class="section"><h2>工具</h2>${choices('tools',a.tools)}</div><div class="section"><h2>知识库</h2>${choices('wiki',a.wiki)}</div><div class="section"><div class="sectionhead"><h2>子 Agent</h2><button data-action="addsub">＋ 添加子 Agent 配置</button></div><p class="muted">主 Agent 根据任务需要创建子 Agent，委派复杂任务与工具执行。模型统一继承主 Agent。</p>${a.subs.length?a.subs.map(x=>`<div class="steps"><div class="sectionhead"><h3>${esc(x.name)}</h3><div class="actions"><button data-subedit="${esc(x.id)}">编辑</button><button data-subremove="${esc(x.id)}">移除</button></div></div><p>${esc(x.desc)}</p><div class="tags"><span class="tag">模型继承主 Agent</span><span class="tag">${x.skills.length} 技能 · ${x.tools.length} 工具 · ${x.wiki.length} 知识库</span></div></div>`).join(''):'<p class="muted">尚未配置子 Agent。添加职责与资源后，主 Agent 可按需委派任务。</p>'}</div></div><div class="panel"><h2>发布后调试</h2><div class="notice">草稿仅用于配置。发布版本后，才能发起调试对话。</div><div class="chatempty"><div class="agenticon">◈</div><h3>${a.published?'已有发布版本 v'+a.published:'尚未发布'}</h3><p>${a.published?'可以调试已发布版本；当前草稿修改需重新发布才会生效。':'完成配置后，点击「发布版本」进入调试。'}</p>${a.published?`<button class="primary" data-action="debugpublished">调试已发布版本 v${a.published}</button>`:'<button disabled>发布后可调试</button>'}</div></div></div>`}
function capture(){const a=agent();if(!$('#config'))return;const name=$('#agentname').value.trim();if(!name){notify('请填写 Agent 名称');return false}a.name=name;a.prompt=$('#prompt').value;a.model=$('#model').value;for(const t of ['skills','tools','wiki'])a[t]=[...document.querySelectorAll(`input[name="${t}"]:checked`)].map(e=>e.value);return true}
function renderChat(){if(!$('#chatarea'))return;if(!chat.length){$('#chatarea').innerHTML=`<div class="chatempty"><div class="agenticon">✧</div><h3>测试你的 Agent</h3><p>发起任务，查看回答、计划与资源调用。</p><button data-action="example">填入示例任务</button></div>`;return}$('#chatarea').innerHTML=chat.map(x=>x.type==='steps'?`<div class="steps"><strong>${esc(x.title)}</strong>${x.steps.map((s,i)=>`<div class="step"><b>${i<x.done?'✓':'○'}</b>${esc(s)}</div>`).join('')}</div>`:tab==='trace'&&x.role==='assistant'?'':`<div class="message ${x.role==='user'?'human':''}"><small>${x.role==='user'?'你':'Agent · 模拟结果'}</small>${esc(x.text)}</div>`).join('');$('#chatarea').scrollTop=$('#chatarea').scrollHeight}
function run(q){if(busy)return;if(page!=='use'||!agent().published||!agent().snapshot){notify('请先发布 Agent，再进行调试');return}const a=agent().snapshot;busy=true;$('#send').disabled=true;$('#send').textContent='执行中';chat.push({role:'user',text:q});let steps=[];if(a.mode==='plan')steps.push('生成任务计划');if(a.skills.length)steps.push('加载技能：'+a.skills.join('、'));if(a.wiki.length)steps.push('检索知识库：'+a.wiki.join('、'));if(a.tools.length)steps.push('调用工具：'+a.tools.join('、'));if(a.subs.length){const complex=/复杂|分析|审查|整理|对比|多步|子任务/.test(q);steps.push(complex?'主 Agent 决定委派子任务（模拟）':'主 Agent 判断任务简单，无需创建子 Agent（模拟）');if(complex)for(const child of a.subs){steps.push('按需创建子 Agent：'+child.name+' · 继承模型 '+a.model);steps.push('子 Agent 职责：'+child.desc);if(child.skills.length)steps.push(child.name+' 加载技能：'+child.skills.join('、'));if(child.wiki.length)steps.push(child.name+' 检索知识库：'+child.wiki.join('、'));if(child.tools.length)steps.push(child.name+' 管理并调用工具：'+child.tools.join('、'));steps.push(child.name+' 返回子任务结果，结束实例')}}steps.push('整理结果与引用');const trace={type:'steps',title:a.mode==='plan'?'自动计划与执行':'ReAct 执行过程',steps,done:0};chat.push(trace);renderChat();steps.forEach((s,i)=>timers.push(setTimeout(()=>{trace.done=i+1;renderChat();if(i===steps.length-1){chat.push({role:'assistant',text:`已完成任务「${q}」的模拟执行。\n\n使用模型：${a.model}\n执行策略：${a.mode==='plan'?'Plan，自动生成计划并执行':'ReAct，逐步决策与执行'}\n\n${a.wiki.length?'示例结论：系统采用事件驱动的执行引擎，智能体通过 Skill 和工具扩展能力。\n引用示例：[1] 团队 Wiki / architecture.md':'示例结论：任务已拆解并汇总，真实回答将在后端接入后生成。'}\n\n此回答为固定演示内容，不代表实际检索或模型输出。`});busy=false;$('#send').disabled=false;$('#send').textContent='运行';renderChat()}},(i+1)*500)))}
function use(){const a=agent(),snap=a.snapshot||a;$('#main').innerHTML=head(esc(a.name),'发布应用 · v'+a.published,'<button data-nav="agents">返回列表</button><button data-edit="'+a.id+'">开发配置</button>')+`<div class="banner"><div><h2 style="margin:0">${esc(snap.name)}</h2></div><span class="tag">${snap.mode==='plan'?'Plan':'ReAct'} · v${a.published}</span></div><div class="split"><div class="panel chat"><div class="tabs"><button data-tab="chat" class="${tab==='chat'?'active':''}">调试对话</button><button data-tab="trace" class="${tab==='trace'?'active':''}">执行记录</button></div><div class="notice">调试已发布版本 v${a.published}；草稿修改不会在此生效。模拟运行，不调用真实模型或工具。</div><div class="chatarea" id="chatarea"></div><form id="chatForm" class="composer"><input id="question" aria-label="消息" placeholder="输入你的任务" required><button class="primary" id="send">运行</button></form></div><div class="panel"><h2>API 调用</h2><p class="muted">以下为拟定接口，Demo 不提供后端服务。</p><span class="tag">POST /api/v1/agents/${esc(a.id)}/runs</span><pre id="api">${esc(`curl -X POST "$AGENT_LOOM_BASE_URL/api/v1/agents/${a.id}/runs" \\\n  -H "Authorization: Bearer $AGENT_LOOM_API_KEY" \\\n  -H "Content-Type: application/json" \\\n  -d '{"input":"整理系统架构","version":${a.published},"stream":true}'`)}</pre><button data-action="copyapi">复制示例</button><h2 style="margin-top:28px">绑定资源</h2><p>模型：${esc(snap.model)}</p><p>Skills：${esc(snap.skills.join('、')||'未绑定')}</p><p>工具：${esc(snap.tools.join('、')||'未绑定')}</p><p>知识库：${esc(snap.wiki.join('、')||'未绑定')}</p><h2>子 Agent 配置</h2>${snap.subs.map(x=>`<div class="steps"><strong>${esc(x.name)}</strong><p>${esc(x.desc)}</p><span class="tag">继承模型 ${esc(snap.model)}</span><p class="muted">按需执行委派任务 · ${x.tools.length} 个工具</p></div>`).join('')||'<p class="muted">未配置</p>'}</div></div>`;renderChat()}
const meta={skills:['Skills','通过 SKILL.md 技能包复用任务方法、脚本与附件。','导入 Skill'],tools:['工具','连接外部 MCP 服务，或托管工具代码。','添加工具'],models:['模型连接','统一管理供应商、模型 ID 和连接配置。','添加模型'],wiki:['知识库','上传 Markdown、TXT、SQL 文本供 Agent 检索。','上传文档']};
function resources(){const [title,desc,btn]=meta[page];$('#main').innerHTML=head(title,desc,`<button class="primary" data-action="addresource">＋ ${btn}</button>`)+`<div class="tablewrap"><table><thead><tr><th>名称</th><th>${page==='models'?'供应商':'用途'}</th><th>${page==='models'?'接口地址':'来源'}</th><th>状态 / 版本</th><th>操作</th></tr></thead><tbody>${db[page].map((r,i)=>`<tr><td><strong>${esc(r.name)}</strong><small>${page==='skills'?'SKILL.md 技能包':page==='tools'?'MCP 标准调用':page==='wiki'?'仅作为检索资料':'服务端保管密钥'}</small></td><td>${esc(r.description)}</td><td>${esc(r.source)}</td><td><span class="tag ${page==='models'?'':'green'}">${esc(r.version)}</span></td><td><button data-detail="${i}">详情</button></td></tr>`).join('')}</tbody></table></div>`+(page==='skills'?'<div class="notice" style="margin-top:20px">完整保留技能目录；格式兼容与运行能力兼容分别验证。专属工具依赖需要适配。</div>':page==='models'?'<div class="notice" style="margin-top:20px">演示中不录入、不保存真实 API Key。具体模型 ID 可随时配置。</div>':page==='tools'?'<div class="notice" style="margin-top:20px">两种来源使用统一工具目录。托管服务由平台运行，外部服务由开发者部署。</div>':'<div class="notice" style="margin-top:20px">SQL 文件只用于理解表结构与示例，不会自动执行数据库语句。</div>')}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal()}
function addResource(){const t=page,[title]=meta[t];modal(`<form id="resourceForm"><h2>${meta[t][2]}</h2><div class="notice">此操作仅模拟导入；文件不会上传到服务器。</div><label for="rname">名称 ${t==='models'?' / 模型 ID':''}</label><input id="rname" required placeholder="${t==='models'?'如 deepseek-chat':'资源名称'}"><label for="rdesc">${t==='models'?'供应商':'用途说明'}</label>${t==='models'?'<select id="rdesc"><option>DeepSeek</option><option>OpenAI</option></select>':'<input id="rdesc" required>'}${t==='skills'||t==='tools'?`<label for="rsource">接入方式</label><select id="rsource">${t==='skills'?'<option>文件夹上传</option><option>Git 地址</option>':'<option>外部 MCP</option><option>平台托管</option>'}</select>`:''}<div id="sourcefields"></div>${t==='models'?'<label for="endpoint">接口地址</label><input id="endpoint" type="url" value="https://api.deepseek.com"><label>API Key</label><input disabled placeholder="Demo 不接受真实密钥">':''}<div id="formerror" class="error" role="alert"></div><div class="actions"><button type="button" data-action="close">取消</button><button class="primary">${t==='models'?'保存配置':'模拟导入'}</button></div></form>`);sourceFields()}
function sourceFields(){const t=page;if(t==='models')return;const source=$('#rsource')?.value||'上传';$('#sourcefields').innerHTML=t==='wiki'?'<label for="files">选择文本文件</label><input id="files" type="file" multiple accept=".md,.markdown,.txt,.sql"><small class="muted">支持 .md / .txt / .sql</small>':source==='Git 地址'?'<label for="address">Git 地址</label><input id="address" type="url" required placeholder="https://example.com/team/skills.git">':source==='外部 MCP'?'<label for="address">MCP 服务地址</label><input id="address" type="url" required placeholder="https://tools.example.com/mcp"><label>认证</label><select><option>无认证（演示）</option><option>服务端保存凭据</option></select>':t==='skills'?'<label for="files">选择技能目录</label><input id="files" type="file" webkitdirectory multiple><small class="muted">目录必须包含 SKILL.md</small>':'<label for="address">工具代码 Git 地址</label><input id="address" type="url" required placeholder="https://example.com/team/tool.git"><label>运行环境</label><select><option>Python 工具 SDK</option></select>'}
function detail(i){const r=db[page][i];modal(`<h2>${esc(r.name)}</h2><p class="muted">${esc(r.description)}</p><div class="tags"><span class="tag">${esc(r.source)}</span><span class="tag green">${esc(r.version)}</span></div>${page==='skills'?`<label>技能目录示例</label><div class="filetree">${esc(r.name)}/<br>├── SKILL.md<br>├── scripts/<br>├── references/<br>└── assets/</div><label>SKILL.md 示例</label><pre>---\nname: ${esc(r.name)}\ndescription: ${esc(r.description)}\n---\n\n# 工作步骤\n1. 读取用户任务与相关资料\n2. 按需调用工具或执行脚本\n3. 整理结果并标注来源</pre>`:page==='tools'?'<label>可发现工具示例</label><div class="filetree">search(query: string)<br>read_document(id: string)</div><p class="muted">这里只展示模拟 schema，不连接真实 MCP 服务。</p>':page==='wiki'?'<label>文件示例</label><div class="filetree">architecture.md<br>process.txt<br>schema.sql</div><p class="muted">生产版本记录解析状态、分块结果与引用位置。</p>':'<label>连接状态</label><div class="notice">尚未连接真实供应商；模型 ID 可编辑，不固定版本。</div>'}<div class="actions"><button data-action="close">关闭</button></div>`)}

function subChoices(type,values){return db[type].map(r=>`<label class="choice"><input type="checkbox" name="sub-${type}" value="${esc(r.name)}" ${values.includes(r.name)?'checked':''}>${esc(r.name)}</label>`).join('')}
function subForm(id){if(capture()===false)return;const x=agent().subs.find(r=>r.id===id)||{id:'',name:'',desc:'',prompt:'',skills:[],tools:[],wiki:[]};modal(`<form id="subForm" data-id="${esc(x.id)}"><h2>${x.id?'编辑':'添加'}子 Agent 配置</h2><div class="notice">运行时由主 Agent 按需创建；模型继承主 Agent：${esc(agent().model)}</div><label for="subname">名称</label><input id="subname" required value="${esc(x.name)}" placeholder="如：资料检索助手"><label for="subdesc">职责与适用任务</label><input id="subdesc" required value="${esc(x.desc)}" placeholder="何时应将任务委派给它"><label for="subprompt">系统 Prompt</label><textarea id="subprompt">${esc(x.prompt)}</textarea><h3 style="margin-top:20px">Skills</h3>${subChoices('skills',x.skills)}<h3>工具</h3>${subChoices('tools',x.tools)}<h3>知识库</h3>${subChoices('wiki',x.wiki)}<div class="actions"><button type="button" data-action="close">取消</button><button class="primary">保存子 Agent 配置</button></div></form>`)}

document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.nav){e.preventDefault();navigate(b.dataset.nav)}else if(b.dataset.edit){current=b.dataset.edit;tab='chat';navigate('editor')}else if(b.dataset.use){current=b.dataset.use;tab='chat';navigate('use')}else if(b.dataset.mode){if(busy){notify('请等待当前模拟运行结束');return}capture();agent().mode=b.dataset.mode;editor()}else if(b.dataset.tab){if(busy){notify('请等待当前模拟运行结束');return}tab=b.dataset.tab;use()}else if(b.dataset.subedit){subForm(b.dataset.subedit)}else if(b.dataset.subremove){if(capture()!==false){agent().subs=agent().subs.filter(x=>x.id!==b.dataset.subremove);save();editor();notify('子 Agent 配置已移除，发布版本不受影响')}}else if(b.dataset.detail!==undefined)detail(Number(b.dataset.detail));else if(b.id==='space')notify('当前演示仅包含产品研发空间');else{const act=b.dataset.action;if(act==='addsub')subForm();if(act==='debugpublished'){if(capture()!==false){save();tab='chat';navigate('use')}}if(act==='close')$('#modal').close();if(act==='addresource')addResource();if(act==='example')$('#question').value='整理系统架构，并解释用户表字段';if(act==='saveagent'&&capture()!==false){save();notify('草稿已保存到当前浏览器');$('#breadcrumb').textContent='产品研发空间 / Agents / 草稿已保存'}if(act==='publish'&&capture()!==false)modal('<h2>发布 Agent</h2><p>将当前配置保存为新版本。网页使用页将运行这份配置快照。</p><div class="notice">这是演示发布，不创建真实服务或 API。</div><div class="actions"><button data-action="close">取消</button><button class="primary" data-action="confirmpublish">确认发布</button></div>');if(act==='confirmpublish'){const a=agent();a.published++;a.snapshot=structuredClone({...a,snapshot:undefined});save();$('#modal').close();notify('已发布演示版本 v'+a.published);navigate('use')}if(act==='copyapi'){navigator.clipboard?.writeText($('#api').textContent).then(()=>notify('已复制 API 示例')).catch(()=>notify('请直接选择并复制示例'));if(!navigator.clipboard)notify('请直接选择并复制示例')}if(act==='newagent')modal('<form id="newForm"><h2>创建 Agent</h2><label for="newname">Agent 名称</label><input id="newname" required placeholder="例如：产品研究助手"><div class="actions"><button type="button" data-action="close">取消</button><button class="primary">创建并配置</button></div></form>')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filter=e.target.value;cards()}});
document.addEventListener('change',e=>{if(e.target.id==='rsource')sourceFields();if(e.target.id==='rdesc'&&page==='models')$('#endpoint').value=e.target.value==='DeepSeek'?'https://api.deepseek.com':'https://api.openai.com/v1'});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='chatForm'){const q=$('#question').value.trim();if(q){$('#question').value='';run(q)}}if(e.target.id==='subForm'){const name=$('#subname').value.trim(),desc=$('#subdesc').value.trim();if(!name||!desc)return;const id=e.target.dataset.id||'sub-'+Date.now();const x={id,name,desc,prompt:$('#subprompt').value};for(const t of ['skills','tools','wiki'])x[t]=[...document.querySelectorAll(`input[name="sub-${t}"]:checked`)].map(e=>e.value);const index=agent().subs.findIndex(r=>r.id===id);if(index<0)agent().subs.push(x);else agent().subs[index]=x;save();$('#modal').close();editor();notify('子 Agent 配置已保存；重新发布后生效')}if(e.target.id==='newForm'){const name=$('#newname').value.trim();if(!name)return;const a={id:'agent-'+Date.now(),name,model:db.models[0].name,mode:'react',prompt:'',skills:[],tools:[],wiki:[],subs:[],published:0};db.agents.push(a);save();current=a.id;$('#modal').close();navigate('editor')}if(e.target.id==='resourceForm'){const name=$('#rname').value.trim();if(!name)return;if(db[page].some(x=>x.name===name)){$('#formerror').textContent='该名称已经存在';return}const files=[...($('#files')?.files||[])];if(page==='wiki'&&(!files.length||files.some(f=>! /\.(md|markdown|txt|sql)$/i.test(f.name)))){$('#formerror').textContent='请选择 Markdown、TXT 或 SQL 文本文件';return}if(page==='skills'&&$('#rsource').value==='文件夹上传'&&!files.some(f=>f.name==='SKILL.md')){$('#formerror').textContent='技能目录必须包含 SKILL.md';return}db[page].push({name,description:$('#rdesc').value,source:page==='models'?$('#endpoint').value:page==='wiki'?'文件上传':$('#rsource').value,version:page==='models'?'演示配置':page==='wiki'?files.length+' 个文件（模拟）':'已导入（模拟）'});save();$('#modal').close();render();notify('已保存演示资源，未进行真实连接或上传')}});
render();
